mapper.select:
select 
from preg_todo t
where t.del_flag = '0'

    and t.done = #{done}


    and t.due_date >= #{from}


    and t.due_date <= #{to}

order by t.done asc, t.due_date asc, t.due_time asc, t.id asc

mapper.update:
update preg_todo set del_flag = '3', version = version + 1, update_time = now(3)
where checkup_id = #{checkupId} and del_flag = '0' and done = 0
  and checkup_occurrence_date >= #{today}

    and checkup_occurrence_date not in
    #{date}

mapper.select:
select t.due_date as dueDate, count(1) as total
from preg_todo t
where t.due_date >= #{from}
  and t.due_date <= #{to}
  and t.del_flag = '0'
group by t.due_date
